// Typed fetch client for the Fairy API.
//
// `paths` is generated by `npm run codegen` from openapi.json. Feature
// services consume the exported `api` instance — full type-safety on
// path, method, request body, and response shape.

import { InjectionToken, Injector, inject } from '@angular/core';
import createClient from 'openapi-fetch';
import { environment } from '../../environments/environment';
import type { paths } from './api.types';
import { AuthService } from './auth.service';

/** Base URL for the backend API. Override via DI in tests / non-default envs. */
export const API_BASE_URL = new InjectionToken<string>('API_BASE_URL', {
  factory: () => environment.apiBaseUrl,
});

/**
 * Returns a typed openapi-fetch client with auth middleware pre-wired.
 *
 * Use from a service:
 * ```ts
 *   private api = injectApi();
 *   async listAgents() {
 *     const { data, error } = await this.api.GET('/api/v1/agents');
 *     ...
 *   }
 * ```
 *
 * Auth middleware (registered once per client instance):
 *   onRequest  — attaches `Authorization: Bearer <token>` when a token exists.
 *   onResponse — on 401 logs out; on 403 fire-and-forgets refresh() so the
 *                status signal stays accurate for the next render cycle.
 *
 * DI cycle note: AuthService itself calls injectApi(), so we cannot call
 * inject(AuthService) here at construction time. Instead we capture the
 * Injector and resolve AuthService lazily inside each middleware callback.
 */
export function injectApi() {
  const baseUrl = inject(API_BASE_URL);
  const injector = inject(Injector);
  const client = createClient<paths>({ baseUrl });

  client.use({
    async onRequest({ request }) {
      const token = injector.get(AuthService).token();
      if (token) {
        request.headers.set('Authorization', `Bearer ${token}`);
      }
      return request;
    },
    async onResponse({ response }) {
      const auth = injector.get(AuthService);
      if (response.status === 401) {
        auth.clearLocalAuth();
      } else if (response.status === 403) {
        void auth.refresh();
      }
      return response;
    },
  });

  return client;
}

export type ApiClient = ReturnType<typeof injectApi>;
